package com.eidolon.sc.mobile;
import org.json.*;
public class HeartSceneTests {
 static int n;static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);n++;System.out.println("PASS "+s);}
 static JSONObject data(double score)throws Exception{JSONObject d=PersonalData.fresh();d.getJSONObject("affinity").put("mano",score);Progression.upgrade(d);HeartScenes.configure(d,true,false);return d;}
 public static void main(String[] args)throws Exception{
  JSONObject d=data(64);d.getJSONObject("affinity").put("mano",66);HeartScenes.gate(d,"mano",64);check(d.getJSONObject("affinity").getDouble("mano")==64.99,"first crossing is held below close");check(HeartScenes.claim(d,"mano").getInt("turns")==0,"crossing starts a scene without consuming a turn");
  for(int i=0;i<6;i++){JSONObject before=new JSONObject(d.toString()),merged=new JSONObject(d.toString()),token=HeartScenes.claim(before,"mano");HeartScenes.delivered(before,merged,"mano",token);d=merged;check(HeartScenes.rows(d,"mano").getJSONObject("close").getInt("turns")==i+1,"one delivered reply advances one scene turn");}
  check(d.getJSONObject("affinity").getDouble("mano")==66&&HeartScenes.rows(d,"mano").getJSONObject("close").getBoolean("done"),"sixth delivered reply opens the door and lifts to 66");check(HeartScenes.claim(d,"mano")==null,"completed scene cannot replay");
  JSONObject early=data(64);early.getJSONObject("affinity").put("mano",65);HeartScenes.gate(early,"mano",64);JSONObject token=HeartScenes.claim(early,"mano");JSONObject cancelled=new JSONObject(early.toString());HeartScenes.delivered(early,cancelled,"mano",null);check(HeartScenes.rows(cancelled,"mano").getJSONObject("close").getInt("turns")==0,"reply without a scene token cannot consume a turn");
  JSONObject committed=new JSONObject(early.toString());HeartScenes.delivered(early,committed,"mano",token);JSONObject duplicate=new JSONObject(committed.toString());HeartScenes.delivered(committed,duplicate,"mano",token);check(HeartScenes.rows(duplicate,"mano").getJSONObject("close").getInt("turns")==1,"stale scene token cannot consume a second turn");
  HeartScenes.configure(early,false,false);HeartScenes.configure(early,true,false);JSONObject stale=new JSONObject(early.toString());HeartScenes.delivered(early,stale,"mano",token);check(HeartScenes.rows(stale,"mano").getJSONObject("close").getInt("turns")==0,"toggle epoch invalidates an in-flight scene token");
  early.getJSONObject("affinity").put("mano",59);check(HeartScenes.claim(early,"mano")==null,"scene pauses more than five points from the door");early.getJSONObject("affinity").put("mano",60);check(HeartScenes.claim(early,"mano")!=null,"scene resumes at five-point boundary");
  JSONObject old=data(90);check(HeartScenes.rows(old,"mano").getJSONObject("intimate").getBoolean("done"),"existing high relationships are preserved when enabling");
  JSONObject gift=data(64);gift.getJSONObject("affinity").put("mano",74);HeartScenes.gate(gift,"mano",64);check(gift.getJSONObject("affinity").getDouble("mano")==64.99&&HeartScenes.rows(gift,"mano").getJSONObject("close").getInt("turns")==0,"large gift-like increase triggers but never completes the scene");
  JSONObject baseline=data(64),staged=new JSONObject(baseline.toString());staged.getJSONObject("affinity").put("mano",66);HeartScenes.gate(staged,"mano",64);HeartScenes.delivered(baseline,staged,"mano",null);check(HeartScenes.rows(staged,"mano").getJSONObject("close").getInt("turns")==0,"new scene survives staged-effect delivery without advancing");
  JSONObject near=data(84);near.getJSONObject("affinity").put("mano",86);HeartScenes.gate(near,"mano",84);check(near.getJSONObject("affinity").getDouble("mano")==84.99&&HeartScenes.claim(near,"mano").getString("tier").equals("intimate"),"intimate has its own independent door");
  JSONObject concurrent=new JSONObject(early.toString());JSONObject currentToken=HeartScenes.claim(concurrent,"mano");JSONObject moved=new JSONObject(concurrent.toString());moved.getJSONObject("affinity").put("mano",64.99);HeartScenes.delivered(concurrent,moved,"mano",currentToken);check(HeartScenes.rows(moved,"mano").getJSONObject("close").getInt("turns")==1,"concurrent gift within the door preserves one reply advancement");
  String raw=d.toString();JSONObject round=new JSONObject(new String(BackupCrypto.decrypt(BackupCrypto.encrypt(raw.getBytes("UTF-8"),"scene-backup".toCharArray()),"scene-backup".toCharArray()),"UTF-8"));PersonalData.validate(round);check(HeartScenes.rows(round,"mano").getJSONObject("close").getBoolean("done"),"encrypted personal-data backup retains completed scene");
  JSONObject minor=new JSONObject().put("age",16).put("scenes",new JSONObject().put("close","认真谈心"));check(HeartScenes.prompt(minor,new JSONObject().put("tier","close").put("turns",0),"female").contains("不表达恋爱"),"minor scene explicitly stays within trust");
  JSONObject paused=data(64);HeartScenes.configure(paused,true,true);paused.getJSONObject("affinity").put("mano",66);HeartScenes.gate(paused,"mano",64);check(paused.getJSONObject("affinity").getDouble("mano")==66,"paused feature leaves ordinary score progression available");
  System.out.println("Passed "+n+" heart scene checks. No API or Android runtime.");
 }
}
